// lib
// Project A: no MessagePack reference.
namespace ProjectA
{
    public class MyType
    {
        public int Id { get; set; }

        // v1 of the library called this "Name"; it has been renamed.
        public string DisplayName { get; set; }
    }
}

// app
// Project B: references Project A and MessagePack.
using MessagePack;
using MessagePack.Formatters;
using ProjectA;

namespace ProjectB
{
    // Surrogate: carries the keys for ProjectA.MyType. Members are matched to the target by name and type.
    internal abstract class MyTypeSurrogate
    {
        [Key(0)]
        public int Id { get; set; }

        // ProjectA.MyType has no member called "Name" -> MsgPack022 (surrogate member not found).
        [Key(1)]
        public string Name { get; set; }
    }

    [GeneratedMessagePackFormatter(SurrogateType = typeof(MyTypeSurrogate))]
    internal partial class MyTypeFormatter : IMessagePackFormatter<MyType>
    {
    }

    internal static class Program
    {
        private static void Main()
        {
            var options = MessagePackSerializerOptions.Standard;
            byte[] bytes = MessagePackSerializer.Serialize(new MyType { Id = 1, DisplayName = "a" }, options);
            System.Console.WriteLine(MessagePackSerializer.ConvertToJson(bytes));
        }
    }
}
